    { t: { ar: "سجل الإصدارات", en: "Version history" }, d: { ar: "ميزة سحابية تعيد الملف إلى أي حالة سابقة", en: "A cloud feature that restores a file to any earlier state" } },
    { t: { ar: "لغة الكتابة واتجاه الفقرة", en: "Keyboard language and paragraph direction" }, d: { ar: "الأولى تحدد الحروف، والثانية تحدد الترتيب — مستقلتان تماماً", en: "The first decides the letters, the second the order — entirely independent" } },
    { t: { ar: "Ctrl+F و Ctrl+H", en: "Ctrl+F and Ctrl+H" }, d: { ar: "بحث يكشف ولا يغيّر، واستبدال يغيّر — و«المزيد» يضبط الدقة", en: "Find reveals without changing; Replace changes — and More adds precision" } },
    { t: { ar: "التفاف النص", en: "Text wrapping" }, d: { ar: "مضمّن · مربع · مشدود · خلف النص — يحدد علاقة الصورة بما حولها", en: "In line, square, tight, behind text — defines the image's relation to its surroundings" } },
    { t: { ar: "فاصل المقطع", en: "Section break" }, d: { ar: "يقسم المستند إلى مقاطع لكل واحد اتجاه صفحته وهوامشه وترقيمه", en: "Splits the document into sections, each with its own orientation, margins, and numbering" } },
    { t: { ar: "فهرس المحتويات", en: "Table of contents" }, d: { ar: "ثمرة الأنماط: يُولَّد بنقرة ويُحدَّث بنقرة من تبويب «مراجع»", en: "The fruit of styles: generated and updated in one click from the References tab" } },
    { t: { ar: "تكرار صفوف الرأس", en: "Repeat header rows" }, d: { ar: "يُظهر عناوين الجدول في أعلى كل صفحة يمتد إليها", en: "Shows the table's titles at the top of every page it spans" } },
    { t: { ar: "تتبّع التغييرات", en: "Track changes" }, d: { ar: "يسجّل تعديل كل مراجع بلونه، ويُقبل أو يُرفض كل تعديل على حدة", en: "Records each reviewer's edits in their colour, accepted or rejected one by one" } },
    { t: { ar: "عناصر الدمج الثلاثة", en: "The three merge elements" }, d: { ar: "قالب + مصدر بيانات + حقول دمج ← مستند لكل سجل", en: "Template, data source, merge fields — one document per record" } },
    { t: { ar: "نطاق الطباعة", en: "Print range" }, d: { ar: "1, 4-6, 9 تطبع صفحات متفرقة بدل المستند كله", en: "1, 4-6, 9 prints scattered pages instead of the whole document" } },
    { t: { ar: "طبقات الحماية", en: "Protection layers" }, d: { ar: "تشفير يمنع الفتح · تقييد تحرير يمنع التعديل · تقييد تنسيق يحمي البنية", en: "Encryption blocks opening, restricted editing blocks changing, restricted formatting protects structure" } }
